11	/// <summary>
12	/// Tests for LocalizationService covering JSON loading, caching, culture switching,
13	/// and fallback behavior.
14	/// </summary>
15	public sealed class LocalizationServiceTests
16	{
17	    [Fact]
18	    public void Instance_ReturnsSameInstance()
19	    {
20	        // Arrange & Act
21	        var instance1 = LocalizationService.Instance;
22	        var instance2 = LocalizationService.Instance;
23	
24	        // Assert
25	        Assert.Same(instance1, instance2);
26	    }
27	
28	    [Fact]
29	    public void CurrentCulture_DefaultsToSystemCulture()
30	    {
31	        // Verifies the culture detection contract: when a locale file exists for the system
32	        // culture, LocalizationService picks it up rather than defaulting to en-US.
33	        // This test does NOT use EnglishLocaleFixture so it observes the singleton's
34	        // actual startup behavior regardless of the running system locale.
35	
36	        // Arrange
37	        var service = LocalizationService.Instance;
38	        var sessionCulture = service.SessionStartCulture;
39	
40	        // The session-start culture must always be a non-empty, parseable culture string.
41	        Assert.False(string.IsNullOrWhiteSpace(sessionCulture));
42	        Assert.True(IsParseable(sessionCulture), $"'{sessionCulture}' is not a valid culture name.");
43	
44	        // When the system UI culture has a matching locale file, the service must have
45	        // detected it — i.e., session-start culture should equal the system culture
46	        // (or its mapped variant) rather than falling back to en-US.
47	        var systemCulture = CultureInfo.CurrentUICulture.Name;
48	        var exeDir = AppDomain.CurrentDomain.BaseDirectory;
49	        var localesPath = Path.Combine(exeDir, "ViewTexts", "Locales");
50	        var systemLocalePath = Path.Combine(localesPath, $"{systemCulture}.json");
51	
52	        if (File.Exists(systemLocalePath))
53	        {
54	            Assert.Equal(systemCulture, sessionCulture);
55	        }
56	        else
57	        {
58	            // Fallback to en-US is correct when no locale file matches the system culture.
59	            Assert.Equal("en-US", sessionCulture);
60	        }
